const CLASS_STORAGE_KEY = "teacher-dashboard-class-management-v1";
const LEGACY_CLASS_STORAGE_KEY = "teacher-tools-class-management-prototype-v2";
const TIMETABLE_STORAGE_KEYS = ["teacher-dashboard-timetable-v1", "cycle-timetable-prototype-v4"];
const RECOVERY_MARKER_KEY = "teacher-dashboard-class-management-3d-recovery-v1";
const TIMETABLE_BACKUP_KEY = "teacher-dashboard-timetable-snapshots-v1";
const RECOVERY_CLASS_NAMES = ["3D"];
const $ = selector => document.querySelector(selector);
const makeId = prefix => `${prefix}-${Date.now()}-${Math.random().toString(16).slice(2)}`;
const esc = (value = "") => { const node = document.createElement("div"); node.textContent = value; return node.innerHTML; };
const sampleData = () => ({ classes: [{ id: "class-3a", name: "3A", students: [{ id: "s-1", seat: "1", name: "陳樂欣", gender: "女" }, { id: "s-2", seat: "2", name: "周子謙", gender: "男" }] }, { id: "class-3b", name: "3B", students: [] }], selectedClassId: "class-3a" });
function readStorage(key) { try { const value = JSON.parse(window.TeacherStorage.getItem(key) || "null"); return value && typeof value === "object" ? value : null; } catch { return null; } }
function normalizeData(value) { value.classes ||= []; value.classes.forEach(item => { item.id ||= makeId("class"); item.students ||= []; item.students.forEach(student => { student.id ||= makeId("student"); student.seat ||= student.studentNo || ""; delete student.studentNo; delete student.guardianContact; student.englishName ||= ""; student.birthday ||= ""; student.notes ||= ""; student.gender ||= ""; }); }); return value; }
function timetableSnapshots() { try { const value = JSON.parse(window.TeacherStorage.getItem(TIMETABLE_BACKUP_KEY) || "[]"); return Array.isArray(value) ? value : []; } catch { return []; } }
function snapshotTimetable(sourceKey, timetable) { try { const snapshots = timetableSnapshots(); const copy = JSON.stringify(timetable); if (!snapshots.some(item => item.sourceKey === sourceKey && JSON.stringify(item.timetable) === copy)) { snapshots.push({ sourceKey, savedAt: new Date().toISOString(), timetable: JSON.parse(copy) }); window.TeacherStorage.setItem(TIMETABLE_BACKUP_KEY, JSON.stringify(snapshots.slice(-12))); } } catch {} }
function restore3DFromSnapshots() { let restored = false; const snapshots = timetableSnapshots(); TIMETABLE_STORAGE_KEYS.forEach(key => { const saved = [...snapshots].reverse().find(item => item.sourceKey === key && item.timetable?.lessons?.["3D"] && Object.keys(item.timetable.lessons["3D"]).length); const current = readStorage(key); if (!saved || !current || (current.lessons?.["3D"] && Object.keys(current.lessons["3D"]).length)) return; current.lessons ||= {}; current.lessons["3D"] = saved.timetable.lessons["3D"]; window.TeacherStorage.setItem(key, JSON.stringify(current)); restored = true; }); return restored; }
function timetableClassNames() { const names = []; TIMETABLE_STORAGE_KEYS.forEach(key => { const timetable = readStorage(key); (timetable?.classes || []).forEach(name => { if (typeof name === "string" && name.trim() && !names.includes(name.trim())) names.push(name.trim()); }); }); if (!window.TeacherStorage.getItem(RECOVERY_MARKER_KEY)) RECOVERY_CLASS_NAMES.forEach(name => { if (!names.includes(name)) names.push(name); }); return names; }
function mergeTimetableClasses(value) { const names = timetableClassNames(); names.forEach(name => { if (!value.classes.some(item => item.name === name)) value.classes.push({ id: makeId("class"), name, students: [] }); }); if (!value.selectedClassId || !value.classes.some(item => item.id === value.selectedClassId)) value.selectedClassId = value.classes[0]?.id || ""; return value; }
function load() { const saved = readStorage(CLASS_STORAGE_KEY) || readStorage(LEGACY_CLASS_STORAGE_KEY) || (window.TeacherCloud.account() ? { classes: [], selectedClassId: "" } : sampleData()); return mergeTimetableClasses(normalizeData(saved)); }
let data = load(); let editor = null; let bulkMode = false; let selectedStudentIds = new Set();
const selectedClass = () => data.classes.find(item => item.id === data.selectedClassId) || data.classes[0];
function syncTimetableClasses(rename) { const names = data.classes.map(item => item.name); TIMETABLE_STORAGE_KEYS.forEach(key => { const original = readStorage(key); const timetable = original || { classes: [], lessons: {} }; snapshotTimetable(key, timetable); timetable.lessons ||= {}; if (rename?.from && rename.from !== rename.to) { if (timetable.lessons[rename.from] && !timetable.lessons[rename.to]) timetable.lessons[rename.to] = timetable.lessons[rename.from]; if (timetable.selectedClass === rename.from) timetable.selectedClass = rename.to; } timetable.classes = names; if (!names.includes(timetable.selectedClass)) timetable.selectedClass = names[0] || ""; window.TeacherStorage.setItem(key, JSON.stringify(timetable)); }); }
function save(rename) { window.TeacherStorage.setItem(CLASS_STORAGE_KEY, JSON.stringify(data)); syncTimetableClasses(rename); }
function recover3DOnce() { if (window.TeacherStorage.getItem(RECOVERY_MARKER_KEY)) return; TIMETABLE_STORAGE_KEYS.forEach(key => { const timetable = readStorage(key); if (!timetable) return; snapshotTimetable(key, timetable); const classes = Array.isArray(timetable.classes) ? [...timetable.classes] : []; RECOVERY_CLASS_NAMES.forEach(name => { if (!classes.includes(name)) classes.push(name); }); timetable.classes = classes; window.TeacherStorage.setItem(key, JSON.stringify(timetable)); }); window.TeacherStorage.setItem(RECOVERY_MARKER_KEY, "done"); window.TeacherStorage.setItem(CLASS_STORAGE_KEY, JSON.stringify(data)); }
function toast(message) { const node = $("#toast"); node.textContent = message; node.classList.add("show"); clearTimeout(toast.timer); toast.timer = setTimeout(() => node.classList.remove("show"), 2200); }
function sortedStudents(students) { return [...students].sort((a, b) => (Number(a.seat) || 9999) - (Number(b.seat) || 9999) || a.name.localeCompare(b.name, "zh-Hant")); }
function genderClass(gender) { return gender === "男" ? "male" : gender === "女" ? "female" : ""; }
function matchingStudents(current) { const query = $("#studentSearch").value.trim().toLowerCase(); return sortedStudents(current.students.filter(student => `${student.seat} ${student.name} ${student.englishName} ${student.gender}`.toLowerCase().includes(query))); }

function render() {
  if (!data.classes.length) { $("#classWorkspace").hidden = true; $("#emptyState").hidden = false; $("#classList").innerHTML = ""; $("#studentGrid").innerHTML = ""; $("#classTitle").textContent = "尚未建立班別"; $("#classMeta").textContent = "共 0 人"; $("#classTotal").textContent = "共 0 個班級"; return; }
  if (!data.classes.some(item => item.id === data.selectedClassId)) data.selectedClassId = data.classes[0].id;
  const current = selectedClass(); const students = matchingStudents(current);
  $("#classWorkspace").hidden = false; $("#emptyState").hidden = true; $("#classTotal").textContent = `共 ${data.classes.length} 個班級`;
  $("#classList").innerHTML = data.classes.map(item => `<article class="class-card ${item.id === current.id ? "active" : ""}"><div class="class-main"><div class="class-avatar">${esc(item.name.slice(0, 1))}</div><div><button class="class-select" type="button" data-class-id="${item.id}">${esc(item.name)}${item.id === current.id ? '<span class="current-badge">✓ 當前</span>' : ""}<small>${item.students.length} 位學生</small></button></div></div><div class="class-actions"><button class="export" type="button" data-action="export-class" data-class-id="${item.id}">⇩ 匯出</button><button type="button" data-action="rename-class" data-class-id="${item.id}" aria-label="重新命名">✎</button><button class="delete" type="button" data-action="archive-class" data-class-id="${item.id}" aria-label="封存班別">▢</button></div></article>`).join("");
  $("#classTitle").textContent = `${current.name} 的學生`; $("#classMeta").textContent = `共 ${current.students.length} 人`; $("#studentCount").textContent = `${current.students.length} 位學生`;
  $("#studentGrid").innerHTML = students.map(student => `<article class="student-card ${selectedStudentIds.has(student.id) ? "selected" : ""}">${bulkMode ? `<input class="select-student" type="checkbox" data-select-student="${student.id}" ${selectedStudentIds.has(student.id) ? "checked" : ""} aria-label="選擇 ${esc(student.name)}" />` : ""}<div class="student-seat">${esc(student.seat || "—")}</div><div class="student-name">${esc(student.name)}</div><div class="tags"><span class="tag ${genderClass(student.gender)}">${esc(student.gender || "未設定性別")}</span></div>${bulkMode ? "" : `<div class="card-actions"><button type="button" data-action="edit-student" data-student-id="${student.id}">詳細</button><button class="move" type="button" data-action="move-student" data-student-id="${student.id}">轉班</button><button class="remove" type="button" data-action="delete-student" data-student-id="${student.id}">刪除</button></div>`}</article>`).join("");
  $("#noResults").hidden = Boolean(students.length); $("#bulkBar").hidden = !bulkMode; $("#bulkToggle").textContent = bulkMode ? "已選擇" : "批量選擇"; $("#bulkInfo").textContent = `已選擇 ${selectedStudentIds.size} 人`;
}
function openEditor(type, payload = {}) {
  editor = { type, ...payload }; const content = $("#dialogContent"); const title = $("#dialogTitle"); const eyebrow = $("#dialogEyebrow"); const submit = $("#dialogSubmit"); const otherClasses = data.classes.filter(item => item.id !== selectedClass()?.id);
  const views = {
    student: () => ({ eyebrow: "學生詳細資料", title: payload.item ? `修改 ${esc(payload.item.name)} 的資料` : "添加學生", submit: "儲存學生", body: `<div class="form-grid"><p class="form-section">基本資料</p><label>學生姓名<input name="name" maxlength="50" required autofocus value="${esc(payload.item?.name || "")}" /></label><label>英文姓名（可留空）<input name="englishName" maxlength="80" value="${esc(payload.item?.englishName || "")}" /></label><label>座號／學號（可留空）<input name="seat" maxlength="10" inputmode="numeric" value="${esc(payload.item?.seat || "")}" /></label><label>性別（可留空）<select name="gender"><option value="">未設定</option><option value="男" ${payload.item?.gender === "男" ? "selected" : ""}>男</option><option value="女" ${payload.item?.gender === "女" ? "selected" : ""}>女</option></select></label><label>出生日期（可留空）<input name="birthday" type="date" value="${esc(payload.item?.birthday || "")}" /></label><p class="form-section">教師備註</p><label>備註（可留空）<textarea name="notes" rows="4" maxlength="500" placeholder="例如：學習需要、課堂觀察或跟進事項">${esc(payload.item?.notes || "")}</textarea></label></div>` }),
    import: () => ({ eyebrow: "匯入學生", title: `添加到 ${selectedClass().name}`, submit: "確認匯入", body: `<div class="import-tabs"><button class="active" type="button" data-import-tab="paste">批量貼上</button><button type="button" data-import-tab="file">CSV 檔案</button></div><div id="pasteImport"><p class="import-help"><strong>可直接從 Excel 複製後貼上。</strong>首行可包含欄位名稱，支援「座號（即學號）、姓名、性別」；姓名為必填。</p><textarea name="list" rows="8" autofocus placeholder="座號\t姓名\t性別\n1\t陳樂欣\t女\n2\t周子謙\t男"></textarea></div><div id="fileImport" hidden><label class="upload-zone">選擇 .csv 名單檔案<input id="studentCsvInput" type="file" accept=".csv,text/csv" /></label><div id="csvPreview" class="import-preview"></div></div>` }),
    transfer: () => ({ eyebrow: "轉班", title: `轉移 ${payload.students.length} 位學生`, submit: "確認轉班", body: otherClasses.length ? `<div class="form-grid"><label>目標班別<select name="targetClassId" required>${otherClasses.map(item => `<option value="${item.id}">${esc(item.name)}（${item.students.length} 人）</option>`).join("")}</select></label></div>` : "<p class=\"import-help\">請先建立另一個班別，才可轉移學生。</p>" })
  }; const view = views[type](); eyebrow.textContent = view.eyebrow; title.textContent = view.title; submit.textContent = view.submit; submit.disabled = type === "transfer" && !otherClasses.length; content.innerHTML = view.body; $("#editorDialog").showModal();
}
function importRows(raw) { const rows = raw.split(/\r?\n/).map(line => line.trim()).filter(Boolean).map(line => line.split(line.includes("\t") ? "\t" : /[,，]/).map(cell => cell.trim())); if (!rows.length) return []; const header = rows[0].map(value => value.replace(/\s/g, "")); const named = header.some(value => /姓名|學生姓名/.test(value)); const index = pattern => header.findIndex(value => pattern.test(value)); const nameIndex = named ? index(/姓名/) : -1; const seatIndex = named ? index(/座號|座位|學號|學生編號/) : -1; const genderIndex = named ? index(/性別/) : -1; return (named ? rows.slice(1) : rows).map(cells => { if (named) return { seat: cells[seatIndex] || "", name: cells[nameIndex] || "", gender: cells[genderIndex] || "" }; const numbered = /^\d+[A-Za-z]*$/.test(cells[0] || ""); return numbered ? { seat: cells[0] || "", name: cells[1] || "", gender: cells[2] || "" } : { seat: "", name: cells[0] || "", gender: cells[1] || "" }; }).filter(row => row.name); }
function addImportedStudents(rows) { const current = selectedClass(); const existing = new Set(current.students.map(student => student.seat).filter(Boolean)); let added = 0; let skipped = 0; rows.forEach(row => { if (row.seat && existing.has(row.seat)) { skipped += 1; return; } current.students.push({ id: makeId("student"), seat: row.seat, name: row.name, gender: ["男", "女"].includes(row.gender) ? row.gender : "", englishName: "", birthday: "", notes: "" }); if (row.seat) existing.add(row.seat); added += 1; }); return { added, skipped }; }
function submitEditor(event) { event.preventDefault(); const form = new FormData(event.currentTarget); const current = selectedClass(); if (editor.type === "student") { const name = String(form.get("name")).trim(); if (!name) return; const values = { name, englishName: String(form.get("englishName")).trim(), seat: String(form.get("seat")).trim(), gender: String(form.get("gender")).trim(), birthday: String(form.get("birthday")).trim(), notes: String(form.get("notes")).trim() }; if (editor.item) Object.assign(editor.item, values); else current.students.push({ id: makeId("student"), ...values }); toast("學生詳細資料已儲存"); } if (editor.type === "import") { const result = addImportedStudents(importRows(String(form.get("list") || ""))); toast(`已加入 ${result.added} 人${result.skipped ? `，略過 ${result.skipped} 個重複座號` : ""}`); } if (editor.type === "transfer") { const destination = data.classes.find(item => item.id === form.get("targetClassId")); if (destination) { const ids = new Set(editor.students.map(item => item.id)); const moving = current.students.filter(item => ids.has(item.id)); current.students = current.students.filter(item => !ids.has(item.id)); destination.students.push(...moving); selectedStudentIds.clear(); bulkMode = false; toast(`已轉移 ${moving.length} 人到 ${destination.name}`); } } save(); $("#editorDialog").close(); render(); }
function download(filename, type, value) { const url = URL.createObjectURL(new Blob([value], { type })); const anchor = document.createElement("a"); anchor.href = url; anchor.download = filename; anchor.click(); URL.revokeObjectURL(url); }
function classCsv(item) { const quote = value => `"${String(value || "").replaceAll('"', '""')}"`; return ["座號,姓名,性別", ...sortedStudents(item.students).map(student => [student.seat, student.name, student.gender].map(quote).join(","))].join("\n"); }
document.addEventListener("click", event => { const classId = event.target.closest("[data-class-id]")?.dataset.classId; if (event.target.closest(".class-select") && classId) { data.selectedClassId = classId; selectedStudentIds.clear(); bulkMode = false; save(); render(); return; } const action = event.target.closest("[data-action]")?.dataset.action; if (!action) return; const current = selectedClass(); const student = current?.students.find(item => item.id === event.target.closest("[data-student-id]")?.dataset.studentId); const actionClass = data.classes.find(item => item.id === classId) || current;
  if (action === "add-student") openEditor("student"); if (action === "edit-student" && student) openEditor("student", { item: student }); if (action === "open-import") openEditor("import"); if (action === "move-student" && student) openEditor("transfer", { students: [student] }); if (action === "open-transfer" && selectedStudentIds.size) openEditor("transfer", { students: current.students.filter(item => selectedStudentIds.has(item.id)) });
  if (action === "toggle-bulk") { bulkMode = !bulkMode; selectedStudentIds.clear(); render(); } if (action === "select-all") { matchingStudents(current).forEach(student => selectedStudentIds.add(student.id)); render(); }
  if (action === "delete-student" && student && confirm(`刪除「${student.name}」？`)) { current.students = current.students.filter(item => item.id !== student.id); save(); render(); toast("已刪除學生"); } if (action === "delete-selected" && selectedStudentIds.size && confirm(`刪除已選擇的 ${selectedStudentIds.size} 位學生？`)) { current.students = current.students.filter(item => !selectedStudentIds.has(item.id)); selectedStudentIds.clear(); bulkMode = false; save(); render(); toast("已刪除學生"); }
  if (action === "rename-class" && actionClass) { const oldName = actionClass.name; const name = prompt("班別名稱", oldName)?.trim(); if (name && !data.classes.some(item => item.name === name && item.id !== actionClass.id)) { actionClass.name = name; save({ from: oldName, to: name }); render(); toast("班別已改名，時間表已同步"); } } if (action === "archive-class" && actionClass && confirm(`封存「${actionClass.name}」及其學生名單？`)) { data.classes = data.classes.filter(item => item.id !== actionClass.id); data.selectedClassId = data.classes[0]?.id || ""; save(); render(); toast("班別已封存"); } if (action === "export-class" && actionClass) { download(`${actionClass.name}-學生名單.csv`, "text/csv;charset=utf-8", `\uFEFF${classCsv(actionClass)}`); toast("正在下載 CSV 名單"); } if (action === "export-all") { download("教師工具-班別備份.json", "application/json", JSON.stringify(data, null, 2)); toast("正在下載全部備份"); } if (action === "reset-demo" && confirm("還原示例只會重設學生名單；時間表內已有班別會保留。是否繼續？")) { data = mergeTimetableClasses(normalizeData(sampleData())); selectedStudentIds.clear(); bulkMode = false; save(); render(); toast("已還原示例資料"); } if (action === "close-dialog") $("#editorDialog").close(); });
document.addEventListener("change", event => { if (event.target.matches("[data-select-student]")) { const id = event.target.dataset.selectStudent; event.target.checked ? selectedStudentIds.add(id) : selectedStudentIds.delete(id); render(); } if (event.target.id === "studentCsvInput") { const file = event.target.files[0]; if (!file) return; const reader = new FileReader(); reader.onload = () => { const rows = importRows(reader.result); $("#csvPreview").innerHTML = rows.slice(0, 4).map(row => `<span>${esc(row.seat || "—")} · ${esc(row.name)} · ${esc(row.gender || "未設定")}</span>`).join(""); $("#pasteImport textarea").value = reader.result; $("#pasteImport").hidden = false; $("#fileImport").hidden = true; toast(`已讀取 ${rows.length} 位學生，請確認匯入`); }; reader.readAsText(file, "utf-8"); } });
document.addEventListener("click", event => { const tab = event.target.closest("[data-import-tab]"); if (!tab) return; const file = tab.dataset.importTab === "file"; document.querySelectorAll("[data-import-tab]").forEach(button => button.classList.toggle("active", button === tab)); $("#pasteImport").hidden = file; $("#fileImport").hidden = !file; });
$("#quickClassForm").addEventListener("submit", event => { event.preventDefault(); const input = event.currentTarget.elements.namedItem("className"); const name = input.value.trim(); if (!name) return; if (data.classes.some(item => item.name === name)) return toast("已有同名班別。"); const item = { id: makeId("class"), name, students: [] }; data.classes.push(item); data.selectedClassId = item.id; input.value = ""; save(); render(); toast("班別已建立，時間表已同步"); });
$("#editorForm").addEventListener("submit", submitEditor); $("#studentSearch").addEventListener("input", render); $("#backupInput").addEventListener("change", event => { const file = event.target.files[0]; if (!file) return; const reader = new FileReader(); reader.onload = () => { try { const imported = JSON.parse(reader.result); if (!Array.isArray(imported.classes)) throw new Error(); data = mergeTimetableClasses(normalizeData(imported)); selectedStudentIds.clear(); save(); render(); toast("已匯入班別備份"); } catch { toast("無法讀取這個備份檔案"); } }; reader.readAsText(file); event.target.value = ""; });
const recoveredLessons = restore3DFromSnapshots(); recover3DOnce(); render(); if (recoveredLessons) toast("已從本機備份還原 3D 時間表");
window.addEventListener("teacher-data-reloaded", () => {
  data = load(); selectedStudentIds.clear(); bulkMode = false; render();
});
